-- =============================================================================
-- load-postgis-step11.sql
--
-- Loads the Step 11 regression modeling table (Cobb County block groups,
-- marginal income+size model) into PostGIS and creates a geometry view
-- for mapping.
--
-- Prerequisites:
--   - Schema acs_5yr_2024 must exist.
--   - Table acs_5yr_2024.arc_bg_geom_2024 must exist (block group geometries).
--   - outputs/regression_modeling_table_step11_cobb_bg.csv must exist
--     (generated by: python run_regression.py --step11-cobb).
--
-- Usage:
--   psql -d <database> -f load-postgis-step11.sql
-- =============================================================================

\set ON_ERROR_STOP on

\echo Loading Step 11 regression modeling table...

-- -------------------------------------------------------------------------
-- 1. Base table
-- -------------------------------------------------------------------------
DROP TABLE IF EXISTS acs_5yr_2024.regression_step11_cobb_bg CASCADE;

CREATE TABLE acs_5yr_2024.regression_step11_cobb_bg (
  geoid                         text PRIMARY KEY,
  state                         text,
  county                        text,
  county_name                   text,
  tract                         text,
  block_group                   text,
  total_res_sqft                bigint,
  residential_record_count      integer,
  parcel_join_status            text,
  total_households              integer,
  -- Income marginals (households by income group)
  I1                            integer,   -- < $27k
  I2                            integer,   -- $27k – $65k
  I3                            integer,   -- $65k – $130k
  I4                            integer,   -- >= $130k
  -- Size marginals (households by number of residents)
  H1                            integer,   -- 1 person
  H2                            integer,   -- 2 persons
  H3                            integer,   -- 3 persons
  H4                            integer,   -- 4 persons
  H5                            integer,   -- 5 persons
  H6                            integer,   -- 6+ persons
  -- 4x6 cross-tab cells (independence approximation)
  I1H1                          integer,
  I1H2                          integer,
  I1H3                          integer,
  I1H4                          integer,
  I1H5                          integer,
  I1H6                          integer,
  I2H1                          integer,
  I2H2                          integer,
  I2H3                          integer,
  I2H4                          integer,
  I2H5                          integer,
  I2H6                          integer,
  I3H1                          integer,
  I3H2                          integer,
  I3H3                          integer,
  I3H4                          integer,
  I3H5                          integer,
  I3H6                          integer,
  I4H1                          integer,
  I4H2                          integer,
  I4H3                          integer,
  I4H4                          integer,
  I4H5                          integer,
  I4H6                          integer,
  -- QA columns
  zero_res_sqft_record_count    integer,
  missing_res_sqft_record_count integer,
  -- Model outputs
  predicted_res_sqft            double precision,
  residual                      double precision
);

\copy acs_5yr_2024.regression_step11_cobb_bg FROM '/nfs/home/sja/repos/census_pecas_download/outputs/regression_modeling_table_step11_cobb_bg.csv' WITH (FORMAT csv, HEADER true)

\echo Loaded regression_step11_cobb_bg.

-- -------------------------------------------------------------------------
-- 2. Geometry view (join to block-group geometries for mapping)
-- -------------------------------------------------------------------------
DROP VIEW IF EXISTS acs_5yr_2024.v_regression_step11_cobb_bg;

CREATE VIEW acs_5yr_2024.v_regression_step11_cobb_bg AS
SELECT
  g.geom,
  d.*
FROM acs_5yr_2024.arc_bg_geom_2024 g
JOIN acs_5yr_2024.regression_step11_cobb_bg d ON d.geoid = g.geoid;

\echo Created view v_regression_step11_cobb_bg.
\echo Done. Query acs_5yr_2024.v_regression_step11_cobb_bg as a GIS layer.
